INSERT INTO chapters(module_id,title,title_translation,description,description_translation,planned_lesson_count,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES (v_module,'Herkunft und Sprachen','مبدأ و زبان‌ها','Raha und Lena sprechen natürlich über Herkunft und Sprachen und übertragen die Muster auf neue Situationen.','رها و لنا به شکل طبیعی درباره مبدأ و زبان‌ها صحبت می‌کنند و الگوها را در موقعیت‌های تازه به کار می‌برند.',4,1,1,2,'validated',JSON_OBJECT('series',2,'contractVersion','3.0.0','foundationRevision','3.2.0','qualityRevision','3.2.1'));
