INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES
(v_chapter,v_c_lena,v_c_raha,'Woher kommst du?','اهل کجایی؟','Beim Kaffee fragt Lena Raha zum ersten Mal nach ihrer Herkunft.','لنا هنگام قهوه برای اولین بار درباره مبدأ رها می‌پرسد.','story','berlin_new_start',5,1,420,1,'validated',JSON_OBJECT('pedagogicalRole','exposure')),
(v_chapter,v_c_lena,v_c_raha,'Welche Sprachen sprichst du?','چه زبان‌هایی صحبت می‌کنی؟','Das Gespräch geht natürlich von Herkunft zu Sprachen weiter.','گفتگو به شکل طبیعی از مبدأ به زبان‌هایی که رها صحبت می‌کند می‌رسد.','story','berlin_new_start',6,1,420,2,'validated',JSON_OBJECT('pedagogicalRole','explicit_form')),
(v_chapter,v_c_lena,v_c_raha,'Kurz über dich','کوتاه درباره خودت','Raha ruft Name, Herkunft und Sprache mit weniger Hilfen ab.','رها نام، مبدأ و زبان را با راهنمایی کمتر از حافظه بازیابی می‌کند.','story','berlin_new_start',7,1,420,3,'validated',JSON_OBJECT('pedagogicalRole','retrieval')),
(v_chapter,v_c_lena,v_c_raha,'Vor dem Nachbarschaftstreffen','پیش از دیدار همسایه‌ها','Lena bereitet Raha auf eine neue Begegnung vor; die Aktivitäten verlangen danach unabhängige Übertragung.','لنا رها را برای یک آشنایی تازه آماده می‌کند و تمرین‌ها انتقال مستقل را می‌سنجند.','story','berlin_new_start',8,1,480,4,'validated',JSON_OBJECT('pedagogicalRole','mastery'));
