(v_l_1,'listen',1,'Woher kommst du?','اول فقط گوش کن.',1,CAST('{"mode":"audio_first","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',2)),(v_l_1,'new_word',2,'Ich komme aus ...','الگوی گفتن مبدأ را به صورت یک تکه یاد بگیر.',1,CAST('{"mode":"chunk_teach","unit_key":"de:a1:ich-komme-aus","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',2)),(v_l_1,'pronunciation',3,'ich','صدای ch در ich را بشنو، تفاوتش با ش و خ را توجه کن، بعد تولید کن.',1,CAST('{"mode":"sound_notice","target":"ich_laut","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',2)),(v_l_1,'speak',4,'Ich komme aus dem Iran.','واضح تکرار کن.',1,CAST('{"mode":"repeat_visible","accepted":["Ich komme aus dem Iran.","Ich komme aus Iran."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_1,'speak',5,'بگو اهل ایران هستی.','از حافظه بگو.',1,CAST('{"mode":"recall_hidden","cue_fa":"بگو اهل ایران هستی.","accepted":["Ich komme aus dem Iran.","Ich komme aus Iran."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_1,'meaning_choice',6,'Ich komme ___ Deutschland.','گزینه درست را انتخاب کن.',1,CAST('{"mode":"sentence_blank","options":["aus","mit","zu"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_1,'reading',7,'Lena kommt aus Deutschland. Raha kommt aus dem Iran.','بخوان و مبدأ هر نفر را پیدا کن.',1,CAST('{"mode":"reading_input","text":"Lena kommt aus Deutschland. Raha kommt aus dem Iran.","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',2)),(v_l_1,'reading_comprehension',8,'Woher kommt Lena?','از متن جواب بده.',1,CAST('{"mode":"reading_inference","options":["aus Deutschland","aus dem Iran","aus Berlin"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_1,'word_order',9,'Ich komme aus Deutschland','مرتب کن.',1,CAST('{"mode":"tap_tokens","tokens":["Deutschland","komme","Ich","aus"],"answer":["Ich","komme","aus","Deutschland"],"input":"tap_toke