(v_l_3,'listen',1,'Ich komme aus dem Iran.','گوش کن و عبارت مبدأ را بازیابی کن.',1,CAST('{"mode":"audio_first","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',2)),(v_l_3,'new_word',2,'ein bisschen Deutsch','عبارت مقدار را مرور کن.',1,CAST('{"mode":"chunk_teach","unit_key":"de:a1:ein-bisschen-deutsch","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',2)),(v_l_3,'pronunciation',3,'ich','بشنو، توجه کن، سپس تولید کن.',1,CAST('{"mode":"sound_notice","target":"ich_laut","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',2)),(v_l_3,'speak',4,'بگو اسم من رهاست.','از حافظه بگو.',1,CAST('{"mode":"recall_hidden","cue_fa":"بگو اسم من رهاست.","accepted":["Ich heiße Raha.","Ich bin Raha."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_3,'speak',5,'بگو اهل ایران هستی.','از حافظه بگو.',1,CAST('{"mode":"recall_hidden","cue_fa":"بگو اهل ایران هستی.","accepted":["Ich komme aus dem Iran.","Aus dem Iran."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_3,'meaning_choice',6,'Ich ___ ein bisschen Deutsch.','انتخاب کن.',1,CAST('{"mode":"sentence_blank","options":["spreche","heiße","komme"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_3,'reading',7,'Raha: Iran, Persisch, ein bisschen Deutsch.','کارت کوتاه را بخوان.',1,CAST('{"mode":"reading_input","text":"Raha: Iran, Persisch, ein bisschen Deutsch.","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',2)),(v_l_3,'reading_comprehension',8,'Was spricht Raha?','اطلاعات درست را انتخاب کن.',1,CAST('{"mode":"reading_inference","options":["Persisch und ein bisschen Deutsch","nur Deutsch","nur Englisch"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_3,'word_order',9,'Woher kommst du','مرتب کن.',1,CAST('{"mode":"tap_tokens","tokens":["du","kommst","Woher"],"answer":["Woher","kommst","du"],"input":"tap_tokens","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_3,'speak',10,'در یک جمع تازه خودت را معرفی کن.','بدون الگوی نمایان پاسخ بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"در یک جمع تازه نام و مبدأت را بگو.","accepted_intents":["Ich heiße Raha. Ich komme aus dem Iran.","Ich bin Raha und komme aus dem Iran."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_3,'speak',11,'بعد زبانت را هم اضافه کن.','پاسخ را گسترش بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"به معرفی قبلی زبانت را هم اضافه کن.","accepted_intents":["Ich spreche Persisch.","Ich spreche Persisch und ein bisschen Deutsch."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_3,'speak',12,'یک معرفی سه بخشی بساز.','نام، مبدأ و زبان را مستقل ترکیب کن.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"یک معرفی سه بخشی برای فردی که قبلا ندیده‌ای بساز.","accepted_intents":["Hallo! Ich heiße Raha. Ich komme aus dem Iran und spreche Persisch.","Guten Morgen! Ich bin Raha, komme aus dem Iran und spreche Persisch."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',2));
INSERT INTO activities(lesson_id,activity_type,sort_order,prompt,instruction,difficulty,config,metadata) VALUES
(v_l_4,'listen',1,'Heute lernst du neue Nachbarn kennen.','گوش کن و موقعیت تازه را بفهم.',1,CAST('{"mode":"audio_first","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',2)),(v_l_4,'reading',2,'Treffen: neue Nachbarn – 18:00','اطلاعیه را بخوان.',1,CAST('{"mode":"reading_input","text":"Treffen: neue Nachbarn – 18:00","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',2)),(v_l_4,'reading_comprehension',3,'Was passiert um 18:00?','از اطلاعیه نتیجه بگیر.',1,CAST('{"mode":"reading_inference","options":["Treffen mit Nachbarn","Deutschprüfung","Frühstück"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_4,'new_word',4,'Woher kommst du?','فقط کاربرد سوال را مرور کن.',1,CAST('{"mode":"chunk_teach","unit_key":"de:a1:woher-kommst-du","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',2)),(v_l_4,'pronunciation',5,'ich','بشنو، توجه کن، سپس واضح تولید کن.',1,CAST('{"mode":"sound_notice","target":"ich_laut","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',2)),(v_l_4,'speak',6,'Ich komme aus dem Iran.','یک بار واضح بگو.',1,CAST('{"mode":"repeat_visible","accepted":["Ich komme aus dem Iran.","Ich komme aus Iran."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_4,'speak',7,'همسایه تازه فقط اسمت را می‌پرسد.','فقط اطلاعات لازم را بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"همسایه تازه فقط اسمت را می‌پرسد.","accepted_intents":["Ich heiße Raha.","Ich bin Raha."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_4,'speak',8,'همسایه بعدی اهل کجایی می‌پرسد.','بدون cue آلمانی جواب بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"همسایه بعدی می‌پرسد اهل کجایی.","accepted_intents":["Ich komme aus dem Iran.","Aus dem Iran."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_4,'meaning_choice',9,'Ich ___ Persisch.','انتخاب کن.',1,CAST('{"mode":"sentence_blank","options":["spreche","komme","heiße"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_4,'word_order',10,'Ich spreche ein bisschen Deutsch','مرتب کن.',1,CAST('{"mode":"tap_tokens","tokens":["Deutsch","bisschen","Ich","ein","spreche"],"answer":["Ich","spreche","ein","bisschen","Deutsch"],"input":"tap_tokens","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_4,'speak',11,'فرد تازه درباره زبانت می‌پرسد.','جواب طبیعی و کوتاه بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"فرد تازه درباره زبانت می‌پرسد.","accepted_intents":["Ich spreche Persisch und ein bisschen Deutsch.","Persisch und ein bisschen Deutsch."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',2)),(v_l_4,'speak',12,'بدون هیچ جمله آلمانی کمکی خودت را معرفی کن.','این mastery نهایی است.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"در دیدار همسایه‌ها بدون هیچ جمله آلمانی کمکی نام، مبدأ و زبانت را بگو.","accepted_intents":["Hallo! Ich heiße Raha. Ich komme aus dem Iran. Ich spreche Persisch und ein bisschen Deutsch.","Guten Abend! Ich bin Raha, komme aus dem Iran und spreche Persisch. Deutsch spreche ich ein bisschen."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',2));
INSERT IGNORE INTO sem_lesson_learning_units(lesson_id,learning_unit_id,learning_role,is_target,exposure_count,evidence_activity_ids,metadata) SELECT v_l_1,id,'new',1,2,JSON_ARRAY(),JSON_OBJECT('series',2) FROM sem_learning_units WHERE course_id=v_course AND unit_key IN('de:a1:ich-komme-aus','de:a1:woher-kommst-du','de:a1:ich-spreche','de:a1:ein-bisschen-deutsch','de:a1:verb-position-1','de:a1:pron:ich-laut','de:a1:can:origin-language');
INSERT IGNORE INTO sem_lesson_learning_units(lesson_id,learning_unit_id,learning_role,is_target,exposure_count,evidence_activity_ids,metadata) SELECT v_l_4,id,'mastery',1,1,JSON_ARRAY(),JSON_OBJECT('series',2) FROM sem_learning_units WHERE course_id=v_course AND unit_key IN('de:a1:ich-komme-aus','de:a1:woher-kommst-du','de:a1:ich-spreche','de:a1:ein-bisschen-deutsch','de:a1:verb-position-1','de:a1:pron:ich-laut','de:a1:can:origin-language');
INSERT IGNORE INTO sem_turn_learning_units(turn_id,learning_unit_id,evidence_type,metadata) SELECT t.id,lu.id,'mastery',JSON_OBJECT('series',2) FROM turns t JOIN sem_learning_units lu ON lu.course_id=v_course AND lu.unit_key='de:a1:can:origin-language' WHERE t.lesson_id=v_l_4 AND t.sort_order=6 LIMIT 1;
INSERT IGNORE INTO sem_review_obligations(course_id,learning_unit_id,origin_chapter_id,due_series,spacing_offset,status,metadata) SELECT v_course,lu.id,v_chapter,2+o.off,o.off,'due',JSON_OBJECT('originSeries',2) FROM sem_learning_units lu JOIN(SELECT 1 off UNION ALL SELECT 2 UNION ALL SELECT 4 UNION ALL SELECT 8 UNION ALL SELECT 16)o WHERE lu.course_id=v_course AND lu.unit_key IN('de:a1:ich-komme-aus','de:a1:woher-kommst-du','de:a1:ich-spreche','de:a1:ein-bisschen-deutsch','de:a1:verb-position-1','de:a1:pron:ich-laut','de:a1:can:origin-language');
